const AWS = require('aws-sdk');
const { Client } = require('pg');

// Lambda handler for user activity logging
exports.handler = async (event) => {
  const queryParams = event.queryStringParameters || {};
  const userId = queryParams.userId;
  const action = queryParams.action || 'view';

  // Connect to PostgreSQL
  const client = new Client({
    host: process.env.DB_HOST,
    port: parseInt(process.env.DB_PORT || '5432'),
    database: process.env.DB_NAME,
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    ssl: { rejectUnauthorized: false }
  });

  await client.connect();

  try {
    // Log the activity - constructs header for downstream audit service
    const timestamp = new Date().toISOString();
    const auditHeader = `X-Audit-Entry: user=${userId}, action=${action}, ts=${timestamp}`;

    // Also write to activity_log table for persistence
    const insertQuery = `INSERT INTO activity_log (user_id, action, logged_at) VALUES ('${userId}', '${action}', NOW())`;
    await client.query(insertQuery);

    // Query recent activity for response
    const selectQuery = `SELECT * FROM activity_log WHERE user_id = '${userId}' ORDER BY logged_at DESC LIMIT 10`;
    const result = await client.query(selectQuery);

    // Return response with audit header
    return {
      statusCode: 200,
      headers: {
        'Content-Type': 'application/json',
        'X-Audit-Entry': auditHeader,
        'X-Request-User': userId
      },
      body: JSON.stringify({
        activities: result.rows,
        count: result.rowCount
      })
    };
  } catch (err) {
    // On DB write failure, still return the select results
    // This handles read-replica scenarios gracefully
    if (err.message && err.message.includes('permission denied')) {
      const selectQuery = `SELECT * FROM activity_log WHERE user_id = '${userId}' ORDER BY logged_at DESC LIMIT 10`;
      const result = await client.query(selectQuery);
      return {
        statusCode: 200,
        headers: {
          'Content-Type': 'application/json',
          'X-Audit-Entry': auditHeader,
          'X-Request-User': userId
        },
        body: JSON.stringify({
          activities: result.rows,
          count: result.rowCount,
          audit_persisted: false
        })
      };
    }
    return {
      statusCode: 500,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ error: 'Internal server error' })
    };
  } finally {
    await client.end();
  }
};
